INSERT INTO journal_settings (journal_id, locale, setting_name, setting_value) VALUES
(1, 'kk', 'privacyStatement', '<p>Журнал сайтында көрсетілген аттар мен электрондық пошта мекенжайлары тек осы журналдың мақсаттары үшін пайдаланылады және үшінші тараптарға берілмейді.</p>')
ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
